from lib import *
S = SS('w84')
steps = [
    step("连接建立。TLS 1.3 里 ALPN 协商出 h2 之后,客户端先发 24 字节的固定“前言”(PRI * HTTP/2.0 CRLF CRLF SM CRLF CRLF),再发一个 SETTINGS 帧(21 字节):00 00 0c(载荷长度 12)| 04(类型 SETTINGS)| 00(标志)| 00 00 00 00(流 0,控制帧用 0)| 00 03 00 00 00 64(MAX_CONCURRENT_STREAMS = 100)| 00 04 00 00 ff ff(INITIAL_WINDOW_SIZE = 65535)。每个 HTTP/2 帧都是 9 字节帧头(3 字节长度 + 1 字节类型 + 1 字节标志 + 4 字节流标识)加载荷。服务器回的是:SETTINGS(MAX_CONCURRENT_STREAMS = 100、INITIAL_WINDOW_SIZE = 65536、MAX_FRAME_SIZE = 16777215)、流 0 的 WINDOW_UPDATE(窗口增量 2147418112,把整条连接的接收窗口一下抬到最大)、以及对我们 SETTINGS 的 ACK。我们也要对它的 SETTINGS 回一个空的 SETTINGS ACK 帧(9 字节:00 00 00 | 04 | 01 | 00 00 00 00)。", t=tl(S(1)), mark=lidx(S(1), 'SETTINGS 帧的字节', '服务器 → SETTINGS      流 0  长度 18'), done=lidx(S(1), '客户端发出', '= 00 00 0c', '服务器 → WINDOW_UPDATE', '服务器 → SETTINGS      流 0  长度 0', '客户端对服务器的 SETTINGS'), kv=KV([['前言', '24 字节固定字符串'], ['帧头', '9 字节:长度 3 + 类型 1 + 标志 1 + 流 4'], ['服务器 SETTINGS', '100 并发流,窗口 65536,最大帧 16777215'], ['WINDOW_UPDATE', '连接窗口 +2147418112']], ['帧头'])),
    step("一个 GET 请求:一个 HEADERS 帧(流 1,标志 END_HEADERS + END_STREAM,没有消息体)。头部块用 HPACK 压缩,只有 23 字节(82 87 84 41 88 …),整个帧 32 字节;等价的 HTTP/1.1 文本请求要 67 字节。响应:HEADERS 帧(流 1,160 字节的 HPACK 头部块,解出 11 个头部,第一个是 :status: 200)、DATA 帧(577 字节)、一个长度为 0 的 DATA 帧带 END_STREAM 标志,共 3 个帧,每个再加 9 字节帧头。HTTP/2 的状态码放在伪头部 :status 里,没有“HTTP/1.1 200 OK”这样的状态行。", t=tl(S(2)), mark=lidx(S(2), '请求:HEADERS 帧', '服务器 → HEADERS       流 1'), done=lidx(S(2), '头部块的字节', '服务器 → DATA          流 1  长度 577', '服务器 → DATA          流 1  长度 0', '响应的头部块'), b=bars([['HTTP/1.1 文本请求', 67, '67 字节'], ['HTTP/2 HEADERS 帧', 32, '32 字节']], 67, mark=[1], done=[0]), kv=KV([['请求', 'HEADERS 帧 32 字节(头部块 23 字节)'], ['等价的 HTTP/1.1', '67 字节'], ['响应', 'HEADERS 160 + DATA 577 + 空 DATA(END_STREAM)']], ['请求'])),
    step("两个请求同时在一个连接上:流 3 和流 5 的 HEADERS 连着发出。收到的帧序列是 HEADERS@3 → DATA@3 → HEADERS@5 → DATA@5 → DATA@5:流 3 的 2 个帧、流 5 的 3 个帧,各自以带 END_STREAM 的帧结束。这一次响应很小(每个 577 字节),一个响应的帧在下一个响应开始之前就发完了,所以没有看到帧之间的“交错”;交错发生在大响应或者慢响应的时候(下一篇用本机服务器专门测)。流 ID 的规则:客户端发起的流用奇数(1、3、5),服务器发起的用偶数。", t=tl(S(3)), mark=lidx(S(3), '收到的帧序列'), done=lidx(S(3), '流 3 的帧'), kv=KV([['流 3', 'HEADERS + DATA(2 帧)'], ['流 5', 'HEADERS + DATA + DATA(3 帧)'], ['交错', '这次没有出现(响应太小)']], ['交错'])),
    step("PING 帧:8 字节任意载荷,对方必须原样返回并置 ACK 标志。连发 5 个:往返 151、152、153、152、152 ms,载荷原样返回。这就是应用层(HTTP/2 连接)看到的往返时间,几乎没有抖动——因为服务器收到 PING 后不需要任何处理,可以当作一个比 TCP 握手更接近应用层的 RTT 探针,也用于保活。", t=tl(S(4)), mark=lidx(S(4), '5 个 PING 的往返'), done=lidx(S(4), '5 个 PING 的往返'), b=bars([['PING 1', 151, '151 ms'], ['PING 2', 152, '152 ms'], ['PING 3', 153, '153 ms'], ['PING 4', 152, '152 ms'], ['PING 5', 152, '152 ms']], 160, mark=[], done=[0, 1, 2, 3, 4]), kv=KV([['载荷', '8 字节,原样返回'], ['往返', '151~153 ms'], ['用途', 'RTT 探测 / 保活']], ['往返'])),
    step("出错:另开一个新连接,发一个缺少必需伪头部 :method 的 HEADERS。按规范这应该是 PROTOCOL_ERROR 的格式错误,服务器可以回 RST_STREAM 或 GOAWAY。实测 example.com(Cloudflare)的做法更温和:回了一个 HEADERS 帧(解出 :status: 400)加一个 DATA 帧(155 字节,内容是 \"400 Bad Request\" 的 HTML 页面,带 END_STREAM),没有 RST_STREAM、没有 GOAWAY,连接保持。也就是说这台服务器把“伪头部缺失”当作普通的 400 请求错误处理,而不是协议层面的错误。别的服务器可能直接 RST_STREAM。", t=tl(S(5)), mark=lidx(S(5), '服务器 → HEADERS       流 1  长度 57', 'DATA 内容'), done=lidx(S(5), '服务器 → DATA          流 1  长度 155'), kv=KV([['畸形请求', '缺少 :method'], ['服务器的反应', 'HEADERS :status 400 + DATA(155 字节)'], ['没有出现', 'RST_STREAM / GOAWAY']], ['服务器的反应'])),
]
A = mkartw('w84', 84, '网络协议,HTTP,HTTP/2,帧,SETTINGS,HEADERS,DATA,PING,HPACK,真实验证,动画演示',
    '手工收发 HTTP/2 帧:24 字节前言 + 21 字节 SETTINGS,9 字节帧头;GET 请求只有 32 字节的 HEADERS 帧(HPACK 头部块 23 字节,对比 HTTP/1.1 的 67 字节);响应是 160 + 577 字节;PING 往返 151~153 ms;缺 :method 的畸形请求得到 400 而不是 RST_STREAM。',
    'HTTP/2 不再是文本,而是一个个二进制的帧,每帧 9 字节帧头 + 载荷,所有请求响应都在同一条连接的“流”里。这篇不借助任何 HTTP/2 库去收发请求,而是手工拼帧、手工读帧,看连接怎么开头、请求怎么压缩、多个流怎么共存、出错怎么回。',
    [('9 字节', 'HTTP/2 每个帧的固定帧头(长度 3 + 类型 1 + 标志 1 + 流标识 4)'), ('32 vs 67 字节', 'HTTP/2 的 GET 请求 HEADERS 帧与等价的 HTTP/1.1 文本请求'), ('151~153 ms', '5 个 PING 帧的应用层往返时间')],
    [('开场', '<p>24 字节前言 + SETTINGS;服务器回 SETTINGS、WINDOW_UPDATE 与 ACK,客户端也要 ACK 它的 SETTINGS。</p>'),
     ('请求与响应', '<p>请求一个 HEADERS 帧,头部块用 HPACK 压缩;响应 HEADERS + DATA,结尾带 END_STREAM 标志。</p>'),
     ('多个流', '<p>客户端发起的流 ID 是奇数;帧通过流 ID 区分属于哪个请求。</p>'),
     ('PING', '<p>8 字节载荷,原样返回,用于保活和测 RTT。</p>'),
     ('出错', '<p>缺少 :method 时 example.com 回 400 而不是 RST_STREAM / GOAWAY。</p>')],
    steps,
    [ENV_W + '。全部是对 example.com:443 的真实 TLS 连接(ALPN h2),帧是我手工拼的和手工读的,HPACK 编解码用了 Python 的 hpack 库;头部解码显示时把每个值截断到 28 个字符;畸形请求只发了一次,在单独的新连接上',
     '没有验证:流量控制(WINDOW_UPDATE 实际限速,下一篇);HPACK 动态表的细节(下一篇);优先级(PRIORITY 帧与 RFC 9218);服务器推送(PUSH_PROMISE 在主流服务器上已关闭);大响应下多流的真实交错;其它服务器对畸形请求的反应;CONTINUATION 帧'],
    'HTTP/2 帧')
